// temp-secret — temporary file that wipes on read
// Mode: strict

fn ts_write::(path, secret) {
    let mem = @mem_from_bytes(@bytes(secret));
    @mem_encrypt(mem, @crypto_random_bytes(32));
    let cipher = @base64(@mem_to_bytes(mem));
    @free(mem);
    @write_text(path, cipher);
    return true;
}

fn ts_read_and_wipe::(path, key) {
    if (!@exists(path)) { return null; }
    let cipher = @base64_decode(@read_text(path));
    let mem = @mem_from_bytes(cipher);
    @mem_decrypt(mem, key);
    let secret = @mem_to_string(mem);
    @mem_secure_wipe(mem);
    @free(mem);
    @remove(path);
    return secret;
}

fn ts_exists::(path) { return @exists(path); }

fn ts_burn::(path) {
    if (@exists(path)) {
        let size = @file_size(path);
        @write_text(path, @repeat("\x00", size));
        @remove(path);
        return true;
    }
    return false;
}

fn version::() { return "1.0.0"; }
